public class WarehouseInfo
{
    public string WarehouseId { get; set; } = "WH-001";
    public string Name { get; set; } = "Warehouse A";

    public static readonly (string Id, string Name)[] AvailableWarehouses =
    [
        ("WH-001", "Warehouse A"),
        ("WH-002", "Warehouse B"),
        ("WH-003", "Warehouse C"),
    ];
}

namespace sv_6439ecd71ca842758a310f82bec56e60.Services;

/// <summary>
/// Scoped service (per-circuit) that tracks low-stock alert counts and
/// notifies all subscribed components when the count changes.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int LastCount { get; private set; }

    /// <summary>
    /// Fired whenever <see cref="LastCount"/> is updated so every
    /// subscriber can re-render — not just the component that polled.
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query returning the number of items below
    /// minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Stores the latest count and notifies all subscribers.
    /// Called by whichever component owns the polling loop.
    /// </summary>
    public void UpdateCount(int count)
    {
        LastCount = count;
        OnChange?.Invoke();
    }
}

