@* Interactive dropdown — lives in the static MainLayout's top bar.
   Uses rendermode InteractiveServer so it can handle change events. *@
@rendermode InteractiveServer
@inject CascadingValueSource<WarehouseInfo> WarehouseSource
@using sv_6439ecd71ca842758a310f82bec56e60.Services
@using Microsoft.AspNetCore.Components

<div class="d-flex align-items-center">
    <label class="me-2 text-nowrap fw-semibold" for="warehouseSelect">Warehouse:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="width: auto;"
            value="@_selectedId"
            @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in WarehouseInfo.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    private string _selectedId = "WH-001";

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? "WH-001";
        var match = WarehouseInfo.AvailableWarehouses
            .FirstOrDefault(w => w.Id == _selectedId);

        var info = new WarehouseInfo
        {
            WarehouseId = match.Id ?? _selectedId,
            Name = match.Name ?? _selectedId
        };

        // Push to every [CascadingParameter] subscriber across all render modes.
        await WarehouseSource.NotifyChangedAsync(info);
    }
}

@* Shows the low-stock alert count as a Bootstrap badge.
   Subscribes to the scoped InventoryAlertService so it updates
   whenever ANY component pushes new data — not just the poller. *@
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_6439ecd71ca842758a310f82bec56e60.Services

@if (AlertService.LastCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-1">@AlertService.LastCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-1">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Wrap in InvokeAsync because the event may fire from a timer
        // callback on a non-Blazor thread.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

