@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_6439ecd71ca842758a310f82bec56e60.Services

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard — @(Warehouse?.Name ?? "unknown")</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(_alertCount > 5 ? "text-danger" : "text-warning")">
                    @_alertCount
                </p>
                <p class="text-muted">
                    items below minimum &bull; refreshes every 10 s
                </p>
            </div>
        </div>
    </div>
</div>

@if (_polling)
{
    <p class="mt-3 text-success">⏱ Polling active for <strong>@Warehouse?.WarehouseId</strong></p>
}

@code {
    /// <summary>
    /// Received via CascadingValueSource — automatically updated when the
    /// user picks a different warehouse in the selector.
    /// </summary>
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private int _alertCount;
    private bool _polling;
    private CancellationTokenSource? _cts;
    private Action? _handler;
    private string? _previousWarehouseId;

    protected override void OnInitialized()
    {
        // Subscribe to alerts raised by the polling loop so this component
        // and every other subscriber (AlertBadge) update together.
        _handler = () => InvokeAsync(() =>
        {
            _alertCount = AlertService.LastCount;
            StateHasChanged();
        });
        AlertService.OnChange += _handler;
    }

    protected override async Task OnParametersSetAsync()
    {
        var currentId = Warehouse?.WarehouseId;
        if (currentId == _previousWarehouseId)
            return;

        // Warehouse changed — restart polling for the new site.
        _previousWarehouseId = currentId;
        await RestartPollingAsync();
    }

    private async Task RestartPollingAsync()
    {
        await StopPollingAsync();
        _cts = new CancellationTokenSource();
        _polling = true;

        // Fetch immediately so the user doesn't wait 10 s for the first value.
        await PollOnceAsync();

        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await PollOnceAsync();
            }
        }
        catch (OperationCanceledException) { /* expected on dispose / warehouse switch */ }
    }

    private async Task PollOnceAsync()
    {
        if (Warehouse is null) return;
        var count = await AlertService.GetLowStockCountAsync(Warehouse.WarehouseId);
        // Push to ALL subscribers — sidebar badge, this page, anything else.
        AlertService.UpdateCount(count);
    }

    private Task StopPollingAsync()
    {
        if (_cts is not null)
        {
            _cts.Cancel();
            _cts.Dispose();
            _cts = null;
        }
        _polling = false;
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

